/* ------------------------------------------------------------------------
   Trajan Pro — the dia Retail Solutions brand face — embedded for jsPDF.

   Two things are worth knowing before using this anywhere:

   1. Trajan is a titling face with no true lowercase. Typing lowercase gives
      small capitals, which is right for headings, names and labels but hard
      going for long paragraphs. The generators therefore set display text in
      Trajan and body copy in a text face; flip BODY_IN_TRAJAN in constants.js
      to put everything in Trajan.
   2. The files here are subset to Latin, punctuation and digits (about 27 KB
      each rather than 500 KB). They carry no rupee glyph, so PDFs continue to
      print "Rs." exactly as they did before.
   ------------------------------------------------------------------------ */

export const TRAJAN = "TrajanPro";

const TRAJAN_REGULAR_B64 = "";

const TRAJAN_BOLD_B64 = "";

/* jsPDF keeps its virtual file system per document, so every new jsPDF
   instance has to be given the fonts before it can select them. */
export function registerBrandFonts(doc) {
  doc.addFileToVFS("TrajanPro-Regular.ttf", TRAJAN_REGULAR_B64);
  doc.addFont("TrajanPro-Regular.ttf", TRAJAN, "normal");
  doc.addFileToVFS("TrajanPro-Bold.ttf", TRAJAN_BOLD_B64);
  doc.addFont("TrajanPro-Bold.ttf", TRAJAN, "bold");
}
